old_main = ".cta-photo-main{position:absolute!important;inset:0!important;background-image:url('assets/cta-final-hq.webp')!important;background-repeat:no-repeat!important;background-position:right center!important;background-size:auto 100%!important;filter:brightness(.98) contrast(1.03) saturate(1.01)!important;pointer-events:none!important;z-index:1!important;-webkit-mask-image:linear-gradient(90deg,transparent 0%,transparent 50%,rgba(0,0,0,.06) 56%,rgba(0,0,0,.16) 61%,rgba(0,0,0,.30) 66%,rgba(0,0,0,.48) 71%,rgba(0,0,0,.66) 76%,rgba(0,0,0,.82) 81%,rgba(0,0,0,.93) 86%,#000 92%,#000 100%)!important;mask-image:linear-gradient(90deg,transparent 0%,transparent 50%,rgba(0,0,0,.06) 56%,rgba(0,0,0,.16) 61%,rgba(0,0,0,.30) 66%,rgba(0,0,0,.48) 71%,rgba(0,0,0,.66) 76%,rgba(0,0,0,.82) 81%,rgba(0,0,0,.93) 86%,#000 92%,#000 100%)!important}"
