old_after = ".cta-panel::after{content:''!important;position:absolute!important;inset:0!important;background:radial-gradient(54% 115% at 84% 44%,rgba(230,200,120,.07) 0%,rgba(201,162,75,.018) 34%,transparent 68%),linear-gradient(180deg,rgba(255,255,255,.012) 0%,transparent 24%,transparent 72%,rgba(0,0,0,.18) 100%),linear-gradient(90deg,#0e0d0b 0%,#0e0d0b 23%,rgba(14,13,11,.998) 30%,rgba(14,13,11,.992) 36%,rgba(14,13,11,.975) 42%,rgba(14,13,11,.94) 48%,rgba(14,13,11,.87) 54%,rgba(14,13,11,.76) 60%,rgba(14,13,11,.62) 66%,rgba(14,13,11,.47) 72%,rgba(14,13,11,.32) 78%,rgba(14,13,11,.20) 83%,rgba(14,13,11,.11) 88%,rgba(14,13,11,.045) 93%,rgba(14,13,11,0) 100%)!important;pointer-events:none!important;z-index:2!important}"
