for old, new, label in [(old_before,new_before,'blur background'),(old_main,new_main,'main photo fade'),(old_after,new_after,'overlay')]:
    if old not in s:
        raise SystemExit('Expected current CTA fragment not found: ' + label)
    s = s.replace(old, new, 1)

p.write_text(s, encoding='utf-8')
